.pv{position:relative;--fg:#171717;--fg2:#525252;--fg3:#737373;--fg4:#A3A3A3;--bg:#fff;--bg2:#FAFAFA;--muted:#F5F5F5;--line:#E5E5E5;--line2:#D4D4D4;--solid:#171717;--on:#fff;
 --err:#B42318;--err-bd:#F04438;--err-bg:#FEF3F2;--focus:#171717;--ring:rgba(23,23,23,.14);--sel:#F5F5F5;--scrim:rgba(10,10,10,.45);--shadow:0 12px 16px -4px rgba(10,13,18,.08),0 4px 6px -2px rgba(10,13,18,.03);
 color:var(--fg);font:14px/20px Inter,system-ui,sans-serif}
.pv[data-theme=dark]{--fg:#F5F5F5;--fg2:#D4D4D4;--fg3:#A3A3A3;--fg4:#737373;--bg:#0A0A0A;--bg2:#111;--muted:#171717;--line:#262626;--line2:#404040;--solid:#F5F5F5;--on:#0A0A0A;
 --err:#FFA19C;--err-bd:#F97066;--err-bg:#3A1210;--focus:#F5F5F5;--ring:rgba(245,245,245,.18);--sel:#1F1F1F;--scrim:rgba(0,0,0,.6);--shadow:0 12px 16px -4px rgba(0,0,0,.5)}
.i{flex:none;display:block}
button{font:inherit;color:inherit}
.ctl.is-hover{border-color:var(--fg3)}
.ctl.is-focus{border-color:var(--focus);box-shadow:inset 0 0 0 1px var(--focus)}
.ctl.is-err.is-focus{box-shadow:inset 0 0 0 1px var(--err-bd)}
.pv[data-state=hover] [data-live]>.ctl{border-color:var(--fg3)}
.pv[data-state=focus] [data-live]>.ctl,.pv[data-state=open] [data-live]>.ctl{border-color:var(--focus);box-shadow:inset 0 0 0 1px var(--focus)}
.pv[data-state=disabled] [data-live]>.ctl{background:var(--muted);color:var(--fg4)}
.pv[data-state=error] [data-live]>.ctl{border-color:var(--err-bd)}
.pv[data-state=readonly] [data-live]>.ctl{background:var(--muted);border-color:var(--line)}
.tg.is-hover{background:var(--bg2);border-color:var(--fg4)}
.tg.is-focus{box-shadow:0 0 0 2px var(--bg),0 0 0 4px var(--focus)}
.mn{border:1px solid var(--line);border-radius:8px;background:var(--bg);box-shadow:var(--shadow);padding:4px;display:flex;flex-direction:column;gap:1px;min-width:200px;box-sizing:border-box;max-height:320px;overflow:auto}
.mi{min-height:36px;display:flex;align-items:center;gap:8px;padding:0 8px;border-radius:6px;font:500 14px/20px Inter;color:var(--fg);cursor:pointer;box-sizing:border-box}
.mi.hov,.mi:hover{background:var(--muted)}
.mi.sel{font-weight:600}
.mi.dis{color:var(--fg4);cursor:not-allowed}
.mi.dis:hover{background:none}
.mi.dang{color:var(--err)}
.pv[data-theme=dark] .chip.ok{background:#053321;color:#75E0A7}
.pv[data-theme=dark] .chip.wa{background:#4E1D09;color:#FEC84B}
.pv[data-theme=dark] .chip.er{background:#55160C;color:#FDA29B}
.sht .mi{min-height:52px;font-size:16px;padding:0 12px;border-radius:10px}
.scr{position:absolute;inset:0;background:var(--scrim);z-index:8}
.bt{height:32px;padding:0 12px;border:1px solid var(--line2);border-radius:8px;background:var(--bg);display:inline-flex;align-items:center;justify-content:center;gap:6px;font:600 13.5px/18px Inter;white-space:nowrap;cursor:pointer;color:var(--fg)}
.bt.pri{background:var(--solid);color:var(--on);border-color:var(--solid)}
.bt.big{height:48px;border-radius:12px;font-size:15px;flex:1}
.bt.ic-only{width:32px;padding:0}
.bt.ghost{border-color:transparent;background:none}
.vg{padding:20px 24px 32px;display:flex;flex-direction:column;gap:20px;background:var(--bg)}
.vg h3{margin:0;font:600 15px/22px Inter;display:flex;gap:8px;align-items:baseline}
.vg h3 small{font:400 12.5px Inter;color:var(--fg3)}
.vgr{display:grid;gap:14px 18px;align-items:start}
.vgc{display:flex;flex-direction:column;gap:6px;min-width:0}
.vgc>.bt{align-self:flex-start}
.vgc>.cap{font:500 11.5px/16px Inter;color:var(--fg3);letter-spacing:.2px}
.vgs{border-top:1px solid var(--line);padding-top:16px;display:flex;flex-direction:column;gap:12px}
.pv[data-platform=mobile] .vg{padding:12px 16px 96px;gap:16px}
.sb{--sbw:256px;width:var(--sbw);box-sizing:border-box;height:100%;min-height:760px;border-right:1px solid var(--line);background:var(--bg);display:flex;flex-direction:column;padding:12px 12px 12px;gap:8px;position:relative;flex:none}
.sbh{display:flex;align-items:center;gap:10px;padding:4px 4px 8px}
.lg{width:32px;height:32px;border-radius:8px;background:var(--solid);color:var(--on);display:grid;place-items:center;font:700 18px Inter;flex:none}
.hd0{display:flex;flex-direction:column;min-width:0;flex:1}
.lgw{font:700 16px/22px Inter;letter-spacing:-.2px}
.tn{display:flex;flex-direction:column;min-width:0}
.tnm{display:none}
.tns{font-size:12.5px;line-height:16px;color:var(--fg3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.clp{border:0;background:none;color:var(--fg3);width:28px;height:28px;border-radius:6px;display:grid;place-items:center;cursor:pointer}
.sbs{display:flex;align-items:center;gap:8px;height:36px;border:1px solid var(--line2);border-radius:8px;padding:0 10px;color:var(--fg4);font-size:14px}
.sbs .kb{margin-left:auto;font:500 11px/16px Inter;color:var(--fg3);border:1px solid var(--line);border-radius:4px;padding:0 4px}
.nv{flex:1;overflow:auto;display:flex;flex-direction:column;gap:0;margin:0 -4px;padding:0 4px}
.grp{display:flex;flex-direction:column;gap:2px}
.gh{font:600 11px/16px Inter;color:var(--fg3);padding:14px 8px 4px}
.ni{position:relative;display:flex;align-items:center;gap:10px;height:36px;padding:0 10px;border-radius:8px;color:var(--fg2);font:500 14px/20px Inter;cursor:pointer;text-decoration:none;min-width:0}
.ni .nic{color:inherit;display:inline-flex;flex:none}
.ni .nl0{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ni:hover,.ni.is-hover{background:var(--muted);color:var(--fg)}
.ni.is-focus{box-shadow:0 0 0 2px var(--bg),0 0 0 4px var(--focus)}
.ni.cur{background:var(--muted);color:var(--fg);font-weight:600}
.ni.cur .nic{color:var(--fg)}
.nb{font:600 11px/18px Inter;border-radius:999px;padding:0 7px;background:var(--muted);color:var(--fg2);border:1px solid var(--line)}
.cv{color:var(--fg3);display:inline-flex;transition:transform .15s}
.cv:not(.op){transform:rotate(-90deg)}
.kids{display:flex;flex-direction:column;gap:2px}
.kids.shut{display:none}
.ni.ch{height:36px;padding-left:38px;font-weight:500}
.cd{display:none}
.tip{display:none}
.fc{border:1px solid var(--line);border-radius:12px;padding:12px;display:flex;flex-direction:column;gap:4px;font-size:13px;line-height:18px;color:var(--fg3);background:var(--bg2)}
.fct{display:flex;gap:6px;align-items:center;color:var(--fg)}
.fct b{font-weight:600}
.fct .i{color:#B54708}
.fc a{font-weight:600;color:var(--fg);text-decoration:underline;text-underline-offset:2px;margin-top:4px}
.scope{display:flex;align-items:center;gap:8px;padding:8px;border-radius:8px;border:1px solid var(--line)}
.sic{width:32px;height:32px;border-radius:8px;background:var(--muted);display:grid;place-items:center;color:var(--fg2);flex:none}
.smm{display:flex;flex-direction:column;min-width:0;flex:1}
.smm b{font:600 13.5px/18px Inter;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.smm span{font-size:12.5px;line-height:16px;color:var(--fg3)}
.sw{color:var(--fg3);display:inline-flex}
.av0{width:32px;height:32px;border-radius:50%;background:#E7EFFD;color:#1F4FB8;display:grid;place-items:center;font:600 12px Inter;flex:none}
.sb.k-slim,.pv[data-state=slim] [data-live-sb] .sb{--sbw:64px!important;padding:12px 8px;align-items:center}
.sb.k-slim :is(.hd0,.sbs span,.sbs .kb,.gh,.nl0,.nb,.cv,.kids,.fc,.smm,.sw,.clp),.pv[data-state=slim] [data-live-sb] .sb :is(.hd0,.sbs span,.sbs .kb,.gh,.nl0,.nb,.cv,.kids,.fc,.smm,.sw){display:none}
.sb.k-slim .ni,.pv[data-state=slim] [data-live-sb] .ni{width:36px;justify-content:center;padding:0}
.sb.k-slim .sbs,.pv[data-state=slim] [data-live-sb] .sbs{width:44px;justify-content:center;padding:0}
.sb.k-slim .scope,.pv[data-state=slim] [data-live-sb] .scope{padding:4px;border:0}
.sb.k-slim .grp:not(.first),.pv[data-state=slim] [data-live-sb] .grp:not(.first){border-top:1px solid var(--line);padding-top:6px;margin-top:6px}
.sb.k-slim .ni:has(.nb)::after,.pv[data-state=slim] [data-live-sb] .ni:has(.nb)::after{content:"";position:absolute;top:6px;right:6px;width:8px;height:8px;border-radius:50%;background:#2E6BE6;border:2px solid var(--bg)}
.pv[data-state=slim] [data-live-sb] .sbh{flex-direction:column}
.pv[data-state=hover] .ni[data-live]{background:var(--muted);color:var(--fg)}
.pv[data-state=focus] .ni[data-live]{box-shadow:0 0 0 2px var(--bg),0 0 0 4px var(--focus)}
.pv[data-state=long] .ni[data-live] .lnorm{display:none}
.pv[data-D1=b] .gh{text-transform:uppercase;letter-spacing:.05em}
.pv[data-D1=c] .gh{font-size:13px;color:var(--fg);padding-top:14px}
.pv[data-D2=b] .ni:has(.cv){flex-direction:row}
.pv[data-D2=b] .ni:has(.cv) .cv{order:-1;margin-left:-6px;margin-right:-6px}
.pv[data-D2=c] .ni .cv{display:none}
.pv[data-D3=a] .kids{margin-left:20px;border-left:1px solid var(--line);padding-left:8px}
.pv[data-D3=a] .ni.ch{padding-left:12px}
.pv[data-D3=c] .ni.ch{padding-left:20px}
.pv[data-D3=c] .cd{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--line2);margin:0 7px}
.pv[data-D3=c] .ni.ch.cur .cd{background:var(--fg)}
.pv[data-D4=b] .nb{background:#E7EFFD;color:#1F4FB8;border:0}
.pv[data-D4=c] .nb{font-size:0;width:8px;height:8px;padding:0;border:0;background:#2E6BE6}
.pv[data-D5=b] .ni.cur{background:var(--muted)}
.pv[data-D5=b] .ni.cur::before{content:"";position:absolute;left:-12px;top:8px;bottom:8px;width:3px;border-radius:0 3px 3px 0;background:var(--fg)}
.pv[data-D5=c] .ni.cur{background:none}
.pv[data-D6=b] .sb .sbs{width:36px;height:36px;padding:0;justify-content:center;position:absolute;top:16px;right:48px;border:0}
.pv[data-D6=b] .sb .sbs :is(span){display:none}
.pv[data-D6=c] .sb .sbs{display:none}
