.pv[data-D7=c] .fc{display:none}
.pv[data-D8=a] .sb.k-slim .ni:hover .tip,.pv[data-D8=a] .sb.k-slim .ni.is-hover .tip,.pv[data-D8=a][data-state=slim] [data-live-sb] .ni:hover .tip{display:block;position:absolute;left:52px;top:8px;background:var(--solid);color:var(--on);font:500 12px/16px Inter;padding:4px 8px;border-radius:6px;white-space:nowrap;z-index:5}
.fly{display:none;position:absolute;left:52px;top:0;z-index:6;width:200px}
.flh{font:600 12px/18px Inter;color:var(--fg3);padding:6px 8px 2px}
